"""Sources collected by the generated CMake: no file list in generated files, same files as the scan."""
import os
from pathlib import Path
import subprocess
import tempfile
import unittest

from cppbuild.cmake_files import entry_path

from cppbuild import CMakeSettings, ProjectType as T, SettingsError, Solution, SolutionBuildSettings
from cppbuild import engine, generators, workspace


class GeneratedFileTests(unittest.TestCase):
    def setUp(self):
        temporary = tempfile.TemporaryDirectory(prefix="cppbuild-sources-")
        self.addCleanup(temporary.cleanup)
        self.root = Path(temporary.name)
        self.solution = Solution.create(self.root / "Demo", "Demo")
        self.app = self.solution.add_project("App", "App", T.EXECUTABLE)
        self.app.add_file("src/main.cpp", content="int main() { return 0; }\n", auto_update=False)

    def documents(self):
        return workspace.plan(self.solution).documents()

    def test_adding_and_removing_files_changes_no_generated_file(self):
        before = self.documents()
        entry = before[entry_path(self.app)]
        self.assertIn('_cppbuild_collect_sources(_cppbuild_sources _cppbuild_modules "src" "include")', entry)
        self.assertNotIn("main.cpp", "".join(before.values()))
        self.assertIn("function(_cppbuild_collect_sources result modules)", before[self.solution.config_directory / "CMakeLists.txt"])
        self.app.add_file("src/more.cpp", content="int more() { return 1; }\n", auto_update=False)
        self.app.add_file("include/more.hpp", content="#pragma once\n", auto_update=False)
        self.assertEqual(self.documents(), before)
        self.app.remove_file("src/more.cpp", auto_update=False)
        self.assertEqual(self.documents(), before)
        values = self.app.settings.get()
        values.source_directories = ["code", "src"]
        self.app.settings.save(values)
        self.assertIn('_cppbuild_collect_sources(_cppbuild_sources _cppbuild_modules "code" "src")',
                      self.documents()[entry_path(self.app)])

    def test_names_a_cmake_list_cannot_hold_are_rejected(self):
        (self.app.root / "src/semi;colon.cpp").write_text("int x;\n")
        with self.assertRaisesRegex(SettingsError, "Unsupported CMake literal"):
            self.documents()


def junction(link, target):
    target.mkdir(parents=True, exist_ok=True)
    if os.name == "nt":
        subprocess.run(["cmd", "/c", "mklink", "/J", str(link), str(target)], check=True, stdout=subprocess.DEVNULL)
    else:
        link.symlink_to(target, target_is_directory=True)


class _RealCollection:
    generator = None

    def test_cmake_collects_what_cppbuild_scans_and_notices_changes(self):
        solution = Solution.create(self.root / "Demo", "Demo")
        app = solution.add_project("App", "App", T.EXECUTABLE)
        add = lambda path, text: app.add_file(path, content=text, auto_update=False)
        add("src/main.cpp", "int a(); int b(); int c();\nint main() { return a() + b() == 3 ? 0 : 1; }\n")
        add("src/[old]/a.cpp", "int a() { return 1; }\n")  # glob characters in a directory name
        add("src/Upper.CPP", "int b() { return 2; }\n")  # compiled, whatever the case of the suffix
        add("src/notes.txt", "listed only\n")
        add("include/app.hpp", "#pragma once\n")
        # Never entered: excluded names, CppBuild's output directories, links; never listed: generated CMake.
        def write(path, text):
            (app.root / path).parent.mkdir(parents=True, exist_ok=True)
            (app.root / path).write_text(text)
        write("src/build/bad.cpp", "#error excluded directory\n")
        write("src/out/bad.cpp", "#error output directory\n")
        write("src/out/.cppbuild-output.json", "{}\n")
        junction(app.root / "src/linked", self.root / "elsewhere")
        (self.root / "elsewhere/bad.cpp").write_text("#error linked directory\n")
        write("src/part/CMakeLists.txt", "# Generated by CppBuild from elsewhere.\n")
        write("src/part/own/CMakeLists.txt", "# written by hand: listed like any file\n")
        settings = SolutionBuildSettings(cmake=CMakeSettings(generator=self.generator))
        solution.set_build_settings(settings)

        report = app.update()
        self.assertTrue(report.success, str(report))
        build = report.build_directory

        def collected():
            data = engine.target_data(build, "Demo_App", "Debug")
            return sorted((solution.root / s["path"]).resolve() for s in data["sources"])
        self.assertEqual(collected(), sorted(p.resolve() for p in report.files))
        self.assertIn((app.root / "src/part/own/CMakeLists.txt").resolve(), collected())
        built = app.build()
        self.assertTrue(built.success, "\n".join(p.output[-3000:] for p in built.processes))

        # Without CppBuild: the next build notices an added and a removed file by itself.
        generated = {p: p.read_bytes() for p in workspace.plan(solution).documents()}
        toolchain = generators.resolve(settings)

        def plain_build():
            result = subprocess.run(["cmake", "--build", str(build), "--config", "Debug"], env=toolchain.env,
                                    stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, errors="replace")
            return result.returncode, result.stdout[-4000:]
        (app.root / "src/c.cpp").write_text("int c() { return 3; }\n")
        (app.root / "src/main.cpp").write_text("int a(); int b(); int c();\nint main() { return a() + b() == c() ? 0 : 1; }\n")
        code, output = plain_build()
        self.assertEqual(code, 0, output)
        self.assertIn((app.root / "src/c.cpp").resolve(), collected())
        (app.root / "src/c.cpp").unlink()
        code, output = plain_build()
        self.assertNotEqual(code, 0, "main.cpp still calls c(), which is no longer built")
        self.assertNotIn((app.root / "src/c.cpp").resolve(), collected())
        self.assertEqual({p: p.read_bytes() for p in generated}, generated)


class _Root:
    def setUp(self):
        temporary = tempfile.TemporaryDirectory(prefix="cppbuild-collect-")
        self.addCleanup(temporary.cleanup)
        self.root = Path(temporary.name)


@unittest.skipUnless(os.environ.get("CPPBUILD_TEST_VS2022") == "1", "Real VS2022 required")
class VS2022CollectionTests(_Root, _RealCollection, unittest.TestCase):
    generator = "Visual Studio 17 2022"


@unittest.skipUnless(os.environ.get("CPPBUILD_TEST_VS2026") == "1", "Real VS2026 required")
class VS2026CollectionTests(_Root, _RealCollection, unittest.TestCase):
    generator = "Visual Studio 18 2026"


@unittest.skipUnless(os.environ.get("CPPBUILD_TEST_NINJA") == "1", "Real Ninja required")
class NinjaCollectionTests(_Root, _RealCollection, unittest.TestCase):
    generator = "Ninja Multi-Config"


if __name__ == "__main__":
    unittest.main()
